<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
if(empty($_SESSION['user'])||($_SESSION['user']['role']??'')!=='admin'){http_response_code(403);exit('Esta sección es exclusiva para administradores.');}
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$_SESSION['csrf']??=bin2hex(random_bytes(24));
require_once $root.'/app/Core/UnifiedSidebar.php';
function uaE($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function uaCsrf():void{if(!hash_equals($_SESSION['csrf'],$_POST['csrf']??'')){http_response_code(419);exit('Solicitud vencida.');}}function uaGo(string $m):never{$_SESSION['msg']=$m;header('Location:?a=users');exit;}
$a=$_GET['a']??'users';$catalog=['dashboard'=>'Panel general','clients'=>'Clientes','partners'=>'Arquitectos y constructoras','products'=>'Productos, precios y stock','projects'=>'Proyectos y presupuestos','technical_projects'=>'Proyectos técnicos','payments'=>'Cobros y pagos','receipts'=>'Recibos','billing'=>'Facturación (próximamente)'];$areas=['comercial'=>'Comercial','tecnico'=>'Técnico','administracion'=>'Administración','gerencial'=>'Gerencial'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 uaCsrf();
 if($a==='save_user'||$a==='update_user'){$id=(int)($_POST['user_id']??0);$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$role=$_POST['role']??'consulta';$profile=(int)($_POST['profile_id']??0)?:null;$password=(string)($_POST['password']??'');$active=isset($_POST['active'])?1:0;if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,['admin','consulta'],true))throw new Exception('Revisá los datos del usuario.');if($role==='admin')$profile=null;elseif(!$profile)throw new Exception('Seleccioná un perfil.');if($a==='save_user'){if(strlen($password)<8)throw new Exception('La clave debe tener al menos 8 caracteres.');$db->prepare('INSERT INTO users(name,email,password_hash,role,profile_id,active) VALUES(?,?,?,?,?,1)')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role,$profile]);uaGo('Usuario creado.');}if($password!==''&&strlen($password)<8)throw new Exception('La nueva clave debe tener al menos 8 caracteres.');if($password!=='')$db->prepare('UPDATE users SET name=?,email=?,password_hash=?,role=?,profile_id=?,active=? WHERE id=?')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role,$profile,$active,$id]);else $db->prepare('UPDATE users SET name=?,email=?,role=?,profile_id=?,active=? WHERE id=?')->execute([$name,$email,$role,$profile,$active,$id]);uaGo('Usuario actualizado.');}
 if($a==='delete_user'){$id=(int)($_POST['user_id']??0);if($id===(int)($_SESSION['user']['id']??0))throw new Exception('No podés borrar el usuario con el que estás conectado.');$s=$db->prepare('SELECT COUNT(*) FROM technical_schedule_users WHERE user_id=?');$s->execute([$id]);$sched=(int)$s->fetchColumn();$s=$db->prepare('SELECT COUNT(*) FROM project_technical_users WHERE user_id=?');try{$s->execute([$id]);$proj=(int)$s->fetchColumn();}catch(Throwable $e){$proj=0;}if($sched||$proj)throw new Exception('Este usuario está asignado a proyectos o jornadas técnicas. Quitá primero esas asignaciones.');$db->prepare('DELETE FROM users WHERE id=?')->execute([$id]);uaGo('Usuario eliminado.');}
 if($a==='save_profile'||$a==='update_profile'){$id=(int)($_POST['profile_id']??0);$name=trim($_POST['name']??'');$area=$_POST['area']??'';if($name===''||!isset($areas[$area]))throw new Exception('Revisá los datos del perfil.');$db->beginTransaction();try{if($a==='save_profile'){$db->prepare('INSERT INTO user_profiles(name,area,active) VALUES(?,?,1)')->execute([$name,$area]);$id=(int)$db->lastInsertId();}else $db->prepare('UPDATE user_profiles SET name=?,area=? WHERE id=?')->execute([$name,$area,$id]);$db->prepare('DELETE FROM profile_module_permissions WHERE profile_id=?')->execute([$id]);$ins=$db->prepare('INSERT INTO profile_module_permissions(profile_id,module_key,can_view,can_manage) VALUES(?,?,?,?)');foreach($catalog as $k=>$v){$manage=!empty($_POST['permissions'][$k]['manage']);$view=$manage||!empty($_POST['permissions'][$k]['view']);$ins->execute([$id,$k,(int)$view,(int)$manage]);}$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}uaGo($a==='save_profile'?'Perfil creado.':'Perfil actualizado.');}
 if($a==='delete_profile'){$id=(int)($_POST['profile_id']??0);$s=$db->prepare('SELECT COUNT(*) FROM users WHERE profile_id=?');$s->execute([$id]);if((int)$s->fetchColumn()>0)throw new Exception('No se puede borrar el perfil porque tiene usuarios asignados. Reasignalos o borralos primero.');$db->beginTransaction();try{$db->prepare('DELETE FROM profile_module_permissions WHERE profile_id=?')->execute([$id]);$db->prepare('DELETE FROM user_profiles WHERE id=?')->execute([$id]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}uaGo('Perfil eliminado.');}
}
$profiles=$db->query("SELECT up.*,COUNT(u.id) users_count FROM user_profiles up LEFT JOIN users u ON u.profile_id=up.id GROUP BY up.id ORDER BY up.area,up.name")->fetchAll();$users=$db->query('SELECT u.*,up.name profile_name,up.area profile_area FROM users u LEFT JOIN user_profiles up ON up.id=u.profile_id ORDER BY u.name')->fetchAll();$editUser=null;if($a==='edit_user'){$s=$db->prepare('SELECT * FROM users WHERE id=?');$s->execute([(int)($_GET['id']??0)]);$editUser=$s->fetch();if(!$editUser){http_response_code(404);exit('Usuario inexistente.');}}$msg=$_SESSION['msg']??null;unset($_SESSION['msg']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Perfiles y usuarios · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui}.main{margin-left:var(--sidebar);padding:30px 4%;max-width:1400px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:11px 8px;border-bottom:1px solid var(--line);text-align:left}th{font-size:12px;color:var(--muted);text-transform:uppercase}.btn{display:inline-block;border:0;border-radius:8px;padding:9px 12px;background:var(--o);color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.light{background:#edf0f3;color:var(--ink)}.danger{background:#fff0f0;color:#a42626;border:1px solid #efcaca}.actions{display:flex;gap:7px;flex-wrap:wrap}.actions form{margin:0}.pill{display:inline-block;padding:4px 8px;background:#edf0f3;border-radius:20px;font-size:12px}input,select{width:100%;padding:10px;border:1px solid #cbd1d7;border-radius:8px;font:inherit}label{display:block;font-weight:700;margin:10px 0 5px}.flash{padding:12px;background:#eefaf5;border:1px solid #bfe8d4;border-radius:9px;margin-bottom:15px}@media(max-width:900px){.main{margin-left:0;padding:18px 12px}.grid{grid-template-columns:1fr}}</style></head><body><?php erpSidebar('users');?><main class="main"><?php if($msg):?><div class="flash"><?=uaE($msg)?></div><?php endif;?><h1>Perfiles y usuarios</h1><div class="grid"><section class="card"><h2>Perfiles</h2><div class="scroll"><table><tr><th>Perfil</th><th>Área</th><th>Usuarios</th><th>Acciones</th></tr><?php foreach($profiles as $p):?><tr><td><b><?=uaE($p['name'])?></b></td><td><?=uaE($areas[$p['area']]??$p['area'])?></td><td><?=$p['users_count']?></td><td><div class="actions"><a class="btn light" href="?a=edit_profile&id=<?=$p['id']?>">Editar</a><form method="post" action="?a=delete_profile" onsubmit="return confirm('¿Eliminar este perfil? Esta acción no se puede deshacer.')"><input type="hidden" name="csrf" value="<?=uaE($_SESSION['csrf'])?>"><input type="hidden" name="profile_id" value="<?=$p['id']?>"><button class="btn danger">Borrar</button></form></div></td></tr><?php endforeach;?></table></div><p><a class="btn" href="?a=edit_profile&id=0">+ Nuevo perfil</a></p></section><section class="card"><h2>Usuarios</h2><div class="scroll"><table><tr><th>Nombre</th><th>Email</th><th>Perfil</th><th>Estado</th><th>Acciones</th></tr><?php foreach($users as $u):?><tr><td><b><?=uaE($u['name'])?></b></td><td><?=uaE($u['email'])?></td><td><?=$u['role']==='admin'?'Administrador':uaE($u['profile_name']??'Sin perfil')?></td><td><span class="pill"><?=$u['active']?'Activo':'Inactivo'?></span></td><td><div class="actions"><a class="btn light" href="?a=edit_user&id=<?=$u['id']?>">Editar</a><?php if((int)$u['id']!==(int)($_SESSION['user']['id']??0)):?><form method="post" action="?a=delete_user" onsubmit="return confirm('¿Eliminar este usuario? Esta acción no se puede deshacer.')"><input type="hidden" name="csrf" value="<?=uaE($_SESSION['csrf'])?>"><input type="hidden" name="user_id" value="<?=$u['id']?>"><button class="btn danger">Borrar</button></form><?php endif;?></div></td></tr><?php endforeach;?></table></div><p><a class="btn" href="?a=edit_user&id=0">+ Nuevo usuario</a></p></section></div><?php if($editUser!==null):?><section class="card"><h2><?=$editUser?'Editar usuario':'Nuevo usuario'?></h2><form method="post" action="?a=<?=$editUser?'update_user':'save_user'?>"><input type="hidden" name="csrf" value="<?=uaE($_SESSION['csrf'])?>"><input type="hidden" name="user_id" value="<?=uaE($editUser['id']??'')?>"><div class="grid"><div><label>Nombre</label><input name="name" value="<?=uaE($editUser['name']??'')?>" required></div><div><label>Email</label><input type="email" name="email" value="<?=uaE($editUser['email']??'')?>" required></div><div><label>Tipo</label><select name="role" id="role"><option value="consulta" <?=($editUser['role']??'consulta')==='consulta'?'selected':''?>>Usuario con perfil</option><option value="admin" <?=($editUser['role']??'')==='admin'?'selected':''?>>Administrador</option></select></div><div id="profile"><label>Perfil</label><select name="profile_id"><option value="">Seleccionar…</option><?php foreach($profiles as $p):?><option value="<?=$p['id']?>" <?=((int)($editUser['profile_id']??0)===(int)$p['id'])?'selected':''?>><?=uaE(($areas[$p['area']]??$p['area']).' · '.$p['name'])?></option><?php endforeach;?></select></div><div><label><?=$editUser?'Nueva clave (dejar vacía para conservar)':'Clave'?></label><input type="password" name="password" minlength="8" <?=$editUser?'':'required'?>></div><?php if($editUser):?><div><label><input style="width:auto" type="checkbox" name="active" value="1" <?=$editUser['active']?'checked':''?>> Usuario activo</label></div><?php endif;?></div><p><button class="btn">Guardar usuario</button> <a class="btn light" href="?a=users">Cancelar</a></p></form><script>const r=document.getElementById('role'),p=document.getElementById('profile');function t(){p.style.display=r.value==='admin'?'none':''}r.onchange=t;t();</script></section><?php endif;?></main></body></html>